ROWS['C2im'] = _C2im

def _Ett(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR1', ''): (-16*sqrt(pi)*al_*g_*omega) + z,
        ('aI1', '_t'): (8*sqrt(pi)*al_*g_) + z,
        ('bR1', ''): (16*sqrt(pi)*al_*f_*omega) + z,
        ('bI1', '_t'): (-8*sqrt(pi)*al_*f_) + z,
        ('H0', ''): (-2*al_*omega*(f_**2 + g_**2)) + z,
        ('H2', ''): (-1/2*al_*(-Lam*al_ - 2*al_ + 8*f_**2*omega*r**2 + 8*g_**2*omega*r**2)/r**2) + z,
        ('H2', '_r'): (al_**2/(X_**2*r)) + z,
        ('K', ''): ((1/2)*al_**2*(Lam - 2)/r**2) + z,
        ('K', '_r'): ((1/2)*al_*(-X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 - 5*al_)/(X_**2*r)) + z,
        ('K', '_rr'): (-al_**2/X_**2) + z,
    }
ROWS['Ett'] = _Ett

def _Etr(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR1', '_t'): (-4*sqrt(pi)*X_*f_) + z,
        ('aI1', ''): (sqrt(pi)*(4*X_**2*al_*f_**2*g_*mu*r**2 + 8*X_**2*al_*f_*g_**2*r - 4*X_**2*al_*g_**3*mu*r**2 + X_**2*al_*g_ + 4*X_**2*f_**2*g_*omega*r**2 + 4*X_**2*g_**3*omega*r**2 - 4*X_*al_*f_*mu*r - 4*X_*al_*g_ - 12*X_*f_*omega*r + 3*al_*g_)/r) + z,
        ('aI1', '_r'): (4*sqrt(pi)*al_*g_) + z,
        ('bR1', '_t'): (-4*sqrt(pi)*X_*g_) + z,
        ('bI1', ''): (-sqrt(pi)*(4*X_**2*al_*f_**3*mu*r**2 + 8*X_**2*al_*f_**2*g_*r - 4*X_**2*al_*f_*g_**2*mu*r**2 + X_**2*al_*f_ + 4*X_**2*f_**3*omega*r**2 + 4*X_**2*f_*g_**2*omega*r**2 + 4*X_*al_*f_ - 4*X_*al_*g_*mu*r + 12*X_*g_*omega*r + 3*al_*f_)/r) + z,
        ('bI1', '_r'): (-4*sqrt(pi)*al_*f_) + z,
        ('H1', ''): (-1/2*(-Lam*al_ + 2*al_*f_**2*mu*r**2 + 4*al_*f_*g_*r - 2*al_*g_**2*mu*r**2 + 8*f_**2*omega*r**2 + 8*g_**2*omega*r**2)/(al_*r**2)) + z,
        ('H2', '_t'): (1/r) + z,
        ('K', '_t'): ((1/2)*(4*X_**2*al_*f_**2*mu*r**2 + 8*X_**2*al_*f_*g_*r - 4*X_**2*al_*g_**2*mu*r**2 + X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 - 3*al_)/(al_*r)) + z,
        ('K', '_tr'): (-1) + z,
    }
ROWS['Etr'] = _Etr

def _Err(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR1', ''): (-2*sqrt(pi)*X_*(4*X_**2*al_*f_**3*mu*r**2 + 8*X_**2*al_*f_**2*g_*r - 4*X_**2*al_*f_*g_**2*mu*r**2 + X_**2*al_*f_ + 4*X_**2*f_**3*omega*r**2 + 4*X_**2*f_*g_**2*omega*r**2 + 4*X_*al_*f_ - 4*X_*al_*g_*mu*r + 4*X_*g_*omega*r + 3*al_*f_)/(al_*r)) + z,
        ('aR1', '_r'): (-8*sqrt(pi)*X_*f_) + z,
        ('bR1', ''): (-2*sqrt(pi)*X_*(4*X_**2*al_*f_**2*g_*mu*r**2 + 8*X_**2*al_*f_*g_**2*r - 4*X_**2*al_*g_**3*mu*r**2 + X_**2*al_*g_ + 4*X_**2*f_**2*g_*omega*r**2 + 4*X_**2*g_**3*omega*r**2 - 4*X_*al_*f_*mu*r - 4*X_*al_*g_ - 4*X_*f_*omega*r + 3*al_*g_)/(al_*r)) + z,
        ('bR1', '_r'): (-8*sqrt(pi)*X_*g_) + z,
        ('H0', ''): ((1/2)*Lam*X_**2/r**2) + z,
        ('H0', '_r'): (-1/r) + z,
        ('H1', '_t'): (2/(al_**2*r)) + z,
        ('H2', ''): (-X_**2*(2*al_*f_**2*mu*r**2 + 4*al_*f_*g_*r - 2*al_*g_**2*mu*r**2 + al_ + 2*f_**2*omega*r**2 + 2*g_**2*omega*r**2)/(al_*r**2)) + z,
        ('K', ''): (-1/2*X_**2*(Lam - 2)/r**2) + z,
        ('K', '_r'): ((1/2)*(4*X_**2*al_*f_**2*mu*r**2 + 8*X_**2*al_*f_*g_*r - 4*X_**2*al_*g_**2*mu*r**2 + X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 + al_)/(al_*r)) + z,
        ('K', '_tt'): (-X_**2/al_**2) + z,
    }
ROWS['Err'] = _Err

def _Etth(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aI1', ''): (4*sqrt(pi)*al_*g_) + z,
        ('aR2', '_t'): (-4*sqrt(pi)*f_*r) + z,
        ('aI2', ''): (2*sqrt(pi)*(4*X_**2*al_*f_**2*g_*mu*r**2 + 8*X_**2*al_*f_*g_**2*r - 4*X_**2*al_*g_**3*mu*r**2 + X_**2*al_*g_ + 4*X_**2*f_**2*g_*omega*r**2 + 4*X_**2*g_**3*omega*r**2 + 2*X_*al_*g_ - 4*X_*f_*omega*r - 3*al_*g_)/X_) + z,
        ('bI1', ''): (-4*sqrt(pi)*al_*f_) + z,
        ('bR2', '_t'): (4*sqrt(pi)*g_*r) + z,
        ('bI2', ''): (2*sqrt(pi)*(4*X_**2*al_*f_**3*mu*r**2 + 8*X_**2*al_*f_**2*g_*r - 4*X_**2*al_*f_*g_**2*mu*r**2 + X_**2*al_*f_ + 4*X_**2*f_**3*omega*r**2 + 4*X_**2*f_*g_**2*omega*r**2 - 2*X_*al_*f_ + 4*X_*g_*omega*r - 3*al_*f_)/X_) + z,
        ('H1', ''): ((1/2)*(2*X_**2*f_**2*mu*r**2 + 4*X_**2*f_*g_*r - 2*X_**2*g_**2*mu*r**2 + X_**2 - 1)/(X_**2*r)) + z,
        ('H1', '_r'): ((1/2)/X_**2) + z,
        ('H2', '_t'): (-1/2) + z,
        ('K', '_t'): (-1/2) + z,
    }
ROWS['Etth'] = _Etth

def _Erth(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
