ROWS['Erth'] = _Erth

def _Ea(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR1', ''): (8*sqrt(pi)*f_*r) + z,
        ('bR1', ''): (-8*sqrt(pi)*g_*r) + z,
        ('H0', ''): ((1/2)*Lam) + z,
        ('H0', '_r'): (-1/4*r*(8*X_**2*al_*f_**2*mu*r**2 + 16*X_**2*al_*f_*g_*r - 8*X_**2*al_*g_**2*mu*r**2 + 3*X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 - al_)/(X_**2*al_)) + z,
        ('H0', '_rr'): (-1/2*r**2/X_**2) + z,
        ('H1', '_t'): (-1/2*r*(-X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 - al_)/(X_**2*al_**3)) + z,
        ('H1', '_tr'): (r**2/(X_**2*al_**2)) + z,
        ('H2', ''): ((1/2)*(-Lam + 8*f_*g_*r)) + z,
        ('H2', '_r'): (-1/4*r*(4*X_**2*al_*f_**2*mu*r**2 + 8*X_**2*al_*f_*g_*r - 4*X_**2*al_*g_**2*mu*r**2 + X_**2*al_ + 4*X_**2*f_**2*omega*r**2 + 4*X_**2*g_**2*omega*r**2 + al_)/(X_**2*al_)) + z,
        ('H2', '_tt'): (-1/2*r**2/al_**2) + z,
        ('K', ''): (-2*f_*g_*r) + z,
        ('K', '_r'): ((1/2)*r*(2*X_**2*f_**2*mu*r**2 + 4*X_**2*f_*g_*r - 2*X_**2*g_**2*mu*r**2 + X_**2 + 1)/X_**2) + z,
        ('K', '_tt'): (-1/2*r**2/al_**2) + z,
        ('K', '_rr'): ((1/2)*r**2/X_**2) + z,
    }
ROWS['Ea'] = _Ea

def _Eb(r, omega, mu, Lam, g_, f_, X_, al_):
    z = np.zeros_like(r)
    return {
        ('aR2', ''): (-8*sqrt(pi)*f_*r) + z,
        ('bR2', ''): (8*sqrt(pi)*g_*r) + z,
        ('H0', ''): (1/2) + z,
        ('H2', ''): (-1/2) + z,
    }
ROWS['Eb'] = _Eb
